use semio_framework_test_fixtures::fixture_text;
use crate::{Number,NativeDecodeControl,RetirementDemand,ValueError,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,retained_clone::{retained_clone_grant_admits,RetainedCloneSource},shared_issuance::SealedShared,owned::{NativeReceive,NativeReceiver},DslValue,retirement::{RetireOwned,controlled::ControlledRetirement}};
#[derive(crate::RetireOwned,crate::NativeReceive)]#[value(crate="crate",native_owned="crate")]struct FlatRow{id:SealedShared<String>,name:SealedShared<String>,value:i64}
struct Bank{stock:RetainedCloneGrant,fuel:u64}
impl Bank{fn new()->Self{let f:serde_json::Value=serde_json::from_str(include_str!("🎟️work/📐️.json")).unwrap();Self{stock:RetainedCloneGrant{maximum_items:f["items"].as_u64().unwrap()as usize,maximum_copy_bytes:f["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:f["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:f["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:f["depth"].as_u64().unwrap()as usize},fuel:f["fuel"].as_u64().unwrap()}}fn available(&self)->RetainedCloneGrant{assert!(self.fuel>0);RetainedCloneGrant{maximum_items:self.stock.maximum_items.min(1),maximum_copy_bytes:self.stock.maximum_copy_bytes.min(4096),..self.stock}}fn quote(&self,d:RetirementDemand)->RetainedCloneGrant{let g=self.available();assert!(retained_clone_grant_admits(g,d));RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth,..g}}fn post(&mut self,p:RetainedCloneProgress,work:u64,heap:(usize,usize),g:RetainedCloneGrant){assert!(p.fits(g));assert!(p.fits(self.stock));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));self.stock.maximum_items-=p.copied_items;self.stock.maximum_copy_bytes-=p.copied_bytes;self.stock.maximum_capacity_bytes-=p.retained_capacity_bytes;self.stock.maximum_release_bytes-=p.released_bytes;self.fuel=self.fuel.checked_sub(work).unwrap();}}
fn observe<R>(f:impl FnOnce()->R)->(R,(usize,usize)){crate::observe_retirement_allocations(f)}
fn drain<T:RetireOwned>(value:T,bank:&mut Bank){let mut owner=ControlledRetirement::new(value).unwrap_or_else(|_|panic!("native original supports closure"));for _ in 0..10000{if owner.terminal_is_empty(){return}let g=bank.quote(owner.next_demand(4096).unwrap());let(result,heap)=observe(||owner.step(g));let work=owner.last_turn_work();let p=match&result{Ok(s)=>s.progress(),Err(e)=>e.retained_progress()};bank.post(p,work,heap,g);result.unwrap();}panic!("native flat fixture close stalled");}
fn source(value:DslValue,bank:&mut Bank)->RetainedCloneSource<DslValue>{crate::source_fixture::capture(value,bank,Bank::available,|bank,p,work,heap,g|bank.post(p,work,heap,g))}
#[test]fn native_flat_record_receive_composes_original_fields_and_every_prefix(){
 let law:serde_json::Value=serde_json::from_str(fixture_text!("../../🧩️record/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();type Receiver=<FlatRow as NativeReceive<DslValue>>::Receiver;let mut finished=0;
 for cut in 0..128{let mut bank=Bank::new();let input=||DslValue::Object(law["canonical"].as_array().unwrap().iter().map(|pair|(pair[0].as_str().unwrap().to_owned(),if let Some(text)=pair[1].as_str(){DslValue::String(text.to_owned())}else{DslValue::Number(Number::Int(pair[1].as_i64().unwrap()))})).collect());let original=source(input(),&mut bank);let foreign=source(input(),&mut bank);let(receiver,heap)=observe(<FlatRow as NativeReceive<DslValue>>::receiver);let mut receiver:Receiver=receiver;assert_eq!(heap,(0,0));let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<20,&mut callback);let mut turns=0;
  while turns<cut&&!receiver.output_ready(){let d=receiver.demands(original.borrow(),4096).unwrap();let g=bank.quote(d);if turns>0{assert!(receiver.demands(foreign.borrow(),4096).is_err());}for axis in 0..5{let mut denied=g;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes=d.copy_bytes-1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes=d.capacity_bytes-1,3 if d.release_bytes>0=>denied.maximum_release_bytes=d.release_bytes-1,4 if d.depth>0=>denied.maximum_depth=d.depth-1,_=>continue}let(turn,heap)=observe(||crate::receive_native_work(&mut control,denied,crate::source_fixture::WorkLoan::new(&bank.fuel,1),|control|receiver.advance(original.borrow(),control,4096,denied)));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(receiver.demands(original.borrow(),4096).unwrap(),d);}let(turn,heap)=observe(||crate::receive_native_work(&mut control,g,crate::source_fixture::WorkLoan::new(&bank.fuel,1),|control|receiver.advance(original.borrow(),control,4096,g)));let p=match&turn.result{Ok(s)=>s.progress(),Err(e)=>e.retained_progress()};bank.post(p,turn.work,heap,g);turn.result.unwrap();turns+=1;}
  if receiver.output_ready(){finished=turns;let g=bank.quote(receiver.take_demand().unwrap());let(turn,heap)=observe(||receiver.take(g));let work=turn.work;let(row,p)=turn.result.unwrap().unwrap();bank.post(p,work,heap,g);assert_eq!(row.id.as_str(),law["expected"]["id"].as_str().unwrap());assert_eq!(row.name.as_str(),law["expected"]["name"].as_str().unwrap());assert_eq!(row.value,law["expected"]["value"].as_i64().unwrap());drain(row,&mut bank);}
  receiver.begin_close();for _ in 0..10000{if receiver.terminal_is_empty(){break}let g=bank.quote(receiver.close_demands(4096).unwrap());let(turn,heap)=observe(||receiver.close_step(g));let p=match&turn.result{Ok(s)=>s.progress(),Err(e)=>e.retained_progress()};bank.post(p,turn.work,heap,g);turn.result.unwrap();}assert!(receiver.terminal_is_empty());drain(original,&mut bank);drain(foreign,&mut bank);if finished>0&&cut>finished{break;}
 }assert!(finished>0);
}
